var t = typeof( Editor.Mcp.SceneTools ); return t.GetMethods( System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static ).Where( m => m.Name == "CreateGameObject" || m.Name == "AddComponent" || m.Name == "DeleteGameObject" || m.Name == "SaveScene" ).Select( m => m.ReturnType.Name + " " + m.Name + "(" + string.Join( ", ", m.GetParameters().Select( p => p.ParameterType.Name + " " + p.Name + ( p.HasDefaultValue ? " = " + p.DefaultValue : "" ) ) ) + ")" ).ToArray();